-- Operator-approved repair (2026-10-12) of the two live brand records that mixed
-- brands (Lenskart held Deli Chic's palette, Mamaearth's slug and assets; Nykaa
-- held a tea brand's slug and the region spelling IND). Generated by a script from
-- read-only SELECTs of the live rows; each statement names its row by id, does
-- nothing on a database that does not hold it, and runs at most once.
-- Moves every value the record says was read from a page on ANOTHER site (by the
-- page's host, decided here at run time) out of brand_extraction.applied into
-- coherence.set_aside, kept with its page and value, never deleted; clears the
-- accepted/overrides lists into history; records the repair; drops field-origin
-- entries that describe no field; adds the restored fields' origins.
create or replace function pg_temp.lc_repair_brand_data(bd jsonb, own_label text, at text, rep jsonb, fo jsonb, fos jsonb)
returns jsonb language sql as $fn$
  with ap as (
    select key, value from jsonb_each(coalesce(bd#>'{brand_extraction,applied}', '{}'::jsonb))
    where coalesce(value->>'source_url', '') ~* '^https?://'
      and substring(value->>'source_url' from '^https?://([^/?#:]+)') !~* ('(^|\.)' || own_label || '\.[a-z.]+$')
  ), moved as (
    select coalesce(array_agg(key), array[]::text[]) as keys,
           coalesce(jsonb_agg(jsonb_build_object('field', key, 'value', value->'value',
             'source_url', split_part(value->>'source_url', '?', 1), 'set_aside_at', at,
             'reason', 'read from ' || substring(value->>'source_url' from '^https?://([^/?#:]+)') || ', not this brand''s own site')), '[]'::jsonb) as rows
    from ap
  )
  select jsonb_set(jsonb_set(jsonb_set(jsonb_set(bd,
    '{brand_extraction,applied}', coalesce(bd#>'{brand_extraction,applied}', '{}'::jsonb) - (select keys from moved)),
    '{coherence}', coalesce(bd->'coherence', '{}'::jsonb) || jsonb_build_object(
      'accepted', '[]'::jsonb, 'overrides', '[]'::jsonb,
      'history', coalesce(bd#>'{coherence,history}', '[]'::jsonb) || jsonb_build_array(jsonb_build_object('at', at,
        'accepted', coalesce(bd#>'{coherence,accepted}', '[]'::jsonb), 'overrides', coalesce(bd#>'{coherence,overrides}', '[]'::jsonb))),
      'set_aside', coalesce(bd#>'{coherence,set_aside}', '[]'::jsonb) || (select rows from moved),
      'repairs', coalesce(bd#>'{coherence,repairs}', '[]'::jsonb) || jsonb_build_array(rep))),
    '{field_origin}', (coalesce(bd->'field_origin', '{}'::jsonb) - 'typography.body.scale' - 'typography.heading.scale' - 'regions.I N.currency' - 'regions.IND.currency') || fo),
    '{field_origins}', (coalesce(bd->'field_origins', '{}'::jsonb) - 'typography.body.scale' - 'typography.heading.scale') || fos)
$fn$;
update brand_workspaces set slug='lenskart', palette=$J${"primary":"#000042","accent":"#4d4d4d","ink":"#000042","muted":"#000042","surface":"#ffffff","surface_alt":"#ffffff","line":"#e4e4e4","ok":"#1a7f37","warn":"#c9a227","err":"#c0392b"}$J$::jsonb, typography=$J${"heading":{"family":"Plus Jakarta Sans","stack":"'Plus Jakarta Sans',system-ui,-apple-system,'Segoe UI',Roboto,Arial,sans-serif","google":true,"weights":"500;700;800"},"body":{"family":"system-ui","stack":"system-ui,-apple-system,'Segoe UI',Roboto,Arial,sans-serif","google":false,"weights":"400;500;600"}}$J$::jsonb, logo_url='https://assets.lenskart.com/images/2026/01/14/Vector-3.svg', asset_hosts='["www.lenskart.com","www.lenskart.sg","assets.lenskart.com","static-web-prod.lenskart.com"]'::jsonb, brand_data = pg_temp.lc_repair_brand_data(brand_data, 'lenskart', '2026-10-11T22:15:00.000Z', $J${"at":"2026-10-11T22:15:00.000Z","reason":"Operator-approved repair (2026-10-11): values read from another site, and labels that did not describe their value, were set aside; values measured on the brand own site restored."}$J$::jsonb, $J${"palette.primary":"site-render","palette.surface":"site-render","palette.surface_alt":"site-render","palette.ink":"site-render","palette.muted":"site-render","palette.accent":"site-render","typography.heading":"site-render","typography.body":"default","logo_url":"site-render"}$J$::jsonb, $J${"palette.primary":{"origin":"site-render","at":"2026-10-11T22:15:00.000Z","url":"https://www.lenskart.com/en-us","signal":"measured on lenskart.com (repair 2026-10-11)"},"palette.surface":{"origin":"site-render","at":"2026-10-11T22:15:00.000Z","url":"https://www.lenskart.com/en-us","signal":"measured on lenskart.com (repair 2026-10-11)"},"palette.surface_alt":{"origin":"site-render","at":"2026-10-11T22:15:00.000Z","url":"https://www.lenskart.com/en-us","signal":"measured on lenskart.com (repair 2026-10-11)"},"palette.ink":{"origin":"site-render","at":"2026-10-11T22:15:00.000Z","url":"https://www.lenskart.com/en-us","signal":"measured on lenskart.com (repair 2026-10-11)"},"palette.muted":{"origin":"site-render","at":"2026-10-11T22:15:00.000Z","url":"https://www.lenskart.com/en-us","signal":"measured on lenskart.com (repair 2026-10-11)"},"palette.accent":{"origin":"site-render","at":"2026-10-11T22:15:00.000Z","url":"https://www.lenskart.com/","signal":"measured on lenskart.com (repair 2026-10-11)"},"typography.heading":{"origin":"site-render","at":"2026-10-11T22:15:00.000Z","url":"https://www.lenskart.com/en-us","signal":"measured on lenskart.com (repair 2026-10-11)"},"typography.body":{"origin":"default","at":"2026-10-11T22:15:00.000Z","signal":"the site read measured no body-copy family; the platform neutral placeholder"},"logo_url":{"origin":"site-render","at":"2026-10-11T22:15:00.000Z","url":"https://www.lenskart.com/en-us","signal":"measured on lenskart.com (repair 2026-10-11)"}}$J$::jsonb), updated_at=now() where id='f2711b60-9e06-403c-84aa-66db0cf82b78' and not coalesce(brand_data#>'{coherence,repairs}','[]'::jsonb) @> '[{"at":"2026-10-11T22:15:00.000Z"}]'::jsonb;
insert into brand_field_provenance (workspace_id, field, origin) select v.w::uuid, v.f, v.o from (values ('f2711b60-9e06-403c-84aa-66db0cf82b78','palette.primary','site-render'),('f2711b60-9e06-403c-84aa-66db0cf82b78','palette.surface','site-render'),('f2711b60-9e06-403c-84aa-66db0cf82b78','palette.surface_alt','site-render'),('f2711b60-9e06-403c-84aa-66db0cf82b78','palette.ink','site-render'),('f2711b60-9e06-403c-84aa-66db0cf82b78','palette.muted','site-render'),('f2711b60-9e06-403c-84aa-66db0cf82b78','palette.accent','site-render'),('f2711b60-9e06-403c-84aa-66db0cf82b78','typography.heading','site-render'),('f2711b60-9e06-403c-84aa-66db0cf82b78','logo_url','site-render')) v(w, f, o) where exists (select 1 from brand_workspaces b where b.id = v.w::uuid) on conflict (workspace_id, field) do update set origin=excluded.origin;
delete from brand_field_provenance where workspace_id='f2711b60-9e06-403c-84aa-66db0cf82b78' and field in ('typography.body');
update brand_catalog_products set stale_at=now() where workspace_id='f2711b60-9e06-403c-84aa-66db0cf82b78' and stale_at is null and coalesce(source_url, product_url, '') ~* '^https?://' and substring(coalesce(source_url, product_url) from '^https?://([^/?#:]+)') !~* '(^|\.)lenskart\.[a-z.]+$';
update brand_workspaces set slug='nykaa', regions=(select jsonb_agg(case when e->>'code'='IND' then jsonb_set(e,'{code}','"IN"') else e end) from jsonb_array_elements(regions) e), catalog_source = case when catalog_source->>'region'='ind' then jsonb_set(catalog_source,'{region}','"in"') else catalog_source end, brand_data = pg_temp.lc_repair_brand_data(brand_data, 'nykaa', '2026-10-11T22:15:00.000Z', $J${"at":"2026-10-11T22:15:00.000Z","reason":"Operator-approved repair (2026-10-11): values read from another site, and labels that did not describe their value, were set aside; values measured on the brand own site restored."}$J$::jsonb, $J${}$J$::jsonb, $J${}$J$::jsonb), updated_at=now() where id='8298f5f2-045f-4f30-89cc-4e5362f2a8d2' and not coalesce(brand_data#>'{coherence,repairs}','[]'::jsonb) @> '[{"at":"2026-10-11T22:15:00.000Z"}]'::jsonb;
